import React from "react";
import "./BudgetLimits.css";

function BudgetLimits({
  budgetLimits,
  setBudgetLimits,
  onNext
}) {

  const handleChange = (category, value) => {
    setBudgetLimits(prev => ({
      ...prev,
      [category]: value
    }));
  };

  return (
    <div className="budget-container">
      <h2 className="budget-title">
        Set Monthly Budget Limits
      </h2>

      <div className="budget-grid">

        <div className="budget-card">
          <h3>Food & Groceries</h3>
          <input
            type="number"
            className="budget-input"
            placeholder="Enter amount"
            value={budgetLimits?.["Food & Groceries"] || ""}
            onChange={(e) =>
              handleChange("Food & Groceries", e.target.value)
            }
          />
        </div>

        <div className="budget-card">
          <h3>Bills</h3>
          <input
            type="number"
            className="budget-input"
            placeholder="Enter amount"
            value={budgetLimits?.["Bills"] || ""}
            onChange={(e) =>
              handleChange("Bills", e.target.value)
            }
          />
        </div>

        <div className="budget-card">
          <h3>Shopping</h3>
          <input
            type="number"
            className="budget-input"
            placeholder="Enter amount"
            value={budgetLimits?.["Shopping"] || ""}
            onChange={(e) =>
              handleChange("Shopping", e.target.value)
            }
          />
        </div>

        <div className="budget-card">
          <h3>Transport</h3>
          <input
            type="number"
            className="budget-input"
            placeholder="Enter amount"
            value={budgetLimits?.["Transport"] || ""}
            onChange={(e) =>
              handleChange("Transport", e.target.value)
            }
          />
        </div>

      </div>

      <button
        className="budget-button"
        onClick={() => onNext(budgetLimits)}
      >
        Save Limits
      </button>
    </div>
  );
}

export default BudgetLimits;
